package day3;

public class ConvertInttoString {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		//int to String
		
		int i = 300;
		System.out.println("Integer Value : " + i);
		
		String str = Integer.toString(i);
		System.out.println("New String Value : " + str);
		
	}

}
